import { useEffect } from 'react';

export default function BlogHeader() {
  useEffect(() => {
    // Load Google Fonts
    const link = document.createElement('link');
    link.href = 'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Roboto:wght@400;500&display=swap';
    link.rel = 'stylesheet';
    document.head.appendChild(link);

    return () => {
      document.head.removeChild(link);
    };
  }, []);

  return (
    <header style={styles.header}>
      <h1 style={styles.heading}>My Personal Blog</h1>
      <p style={styles.subtitle}>Thoughts, ideas, and musings</p>
    </header>
  );
}

const styles = {
  header: {
    textAlign: 'center',
    padding: '2rem 0',
    backgroundColor: '#f8f9fa',
    borderBottom: '1px solid #e9ecef'
  },
  heading: {
    fontFamily: "'Playfair Display', serif",
    fontSize: '2.5rem',
    margin: '0 0 0.5rem 0',
    color: '#2c3e50',
    fontWeight: 700,
    letterSpacing: '0.5px'
  },
  subtitle: {
    fontFamily: "'Roboto', sans-serif",
    fontSize: '1.1rem',
    margin: '0',
    color: '#6c757d',
    fontWeight: 400
  }
};

